Add Task to Section of Project.code:
// Move a task into a section of a project.
request(`/sections/${$.data.sectionGid}/addTask`, {
  method: 'POST',
  body: {
    data: {
      // The task to add to the section.
      task: $.data.taskGid,
    },
  },
});

Create Comment/Story.code:
// Add a comment / story to a task.
createTaskStory(
  // 1) The task's globally unique id.
  $.data.taskGid,
  {
    // 2) The comment body (HTML supported when html_text is used).
    text: 'Status update: imported from the upstream system.',
  }
);

Create Duplicate Task.code:
// Duplicate an existing task.
request(`/tasks/${$.data.taskGid}/duplicate`, {
  method: 'POST',
  body: {
    data: {
      // Name for the new task.
      name: `Copy of ${$.data.taskName}`,
      // Comma-separated list of fields to copy over.
      include: 'assignee,notes,projects,subtasks,tags',
    },
  },
});

Create Project.code:
// Create a new project in a workspace.
request('/projects', {
  method: 'POST',
  body: {
    data: {
      name: 'Measles vaccination campaign 2026',
      notes: 'Tracks outreach, cold chain and reporting tasks.',
      workspace: $.configuration.workspaceGid,
      // Required for organisation workspaces: the owning team gid.
      team: $.data.teamGid,
    },
  },
});

Create Section.code:
// Create a new section within a project.
request(`/projects/${$.data.projectGid}/sections`, {
  method: 'POST',
  body: {
    data: {
      name: 'Awaiting lab results',
    },
  },
});

Create Task.code:
// Create a new task.
createTask({
  // The task's title.
  name: 'Follow up with patient',
  // Long-form description (optional).
  notes: `Imported from upstream system on ${new Date().toISOString()}`,
  // Workspace gid this task lives in.
  workspace: $.configuration.workspaceGid,
  // Optional: place the task into a project on creation.
  projects: [$.data.projectGid],
  // Optional: assign to a user gid.
  assignee: $.data.assigneeGid,
  // Optional ISO date string.
  due_on: '2026-06-01',
});

Create Task From Template.code:
// Create a task from a task template.
request(`/task_templates/${$.data.taskTemplateGid}/instantiateTask`, {
  method: 'POST',
  body: {
    data: {
      // Name of the new task.
      name: `Home visit: ${$.data.householdId}`,
    },
  },
});

Update Task.code:
// Update properties on an existing task.
updateTask(
  // 1) Task gid.
  $.data.taskGid,
  // 2) Fields to change.
  {
    name: 'Updated task title',
    completed: true,
    notes: 'Closed after upstream sync.',
  }
);

API Request (Beta).code:
// Make an arbitrary request against the Asana API.
// Path is relative to the Asana base URL.
request('/workspaces', {
  method: 'GET',
  query: { limit: 10 },
});

Find All Tasks From Project.code:
// List tasks in a project.
getTasks(
  // 1) Project gid.
  $.data.projectGid,
  // 2) Query params.
  {
    // Fields to return per task.
    opt_fields: 'name,notes,assignee,completed,due_on',
    // Cap the result size.
    limit: 100,
  }
);

Find Project.code:
// Find projects in a workspace whose name matches a search term.
request(`/workspaces/${$.configuration.workspaceGid}/typeahead`, {
  query: {
    resource_type: 'project',
    query: $.data.projectName,
    count: 5,
  },
});

Find Section in Project.code:
// List the sections in a project, then keep the one matching a name.
request(`/projects/${$.data.projectGid}/sections`, {
  query: { opt_fields: 'name' },
});

fn(state => {
  state.data = state.data.find(section => section.name === 'Awaiting lab results');
  return state;
});

Find Task Comments.code:
// List the stories on a task, then keep only the comments.
request(`/tasks/${$.data.taskGid}/stories`, {
  query: { opt_fields: 'type,text,created_by.name,created_at' },
});

fn(state => {
  state.data = state.data.filter(story => story.type === 'comment');
  return state;
});

Find Tasks in Workspace.code:
// Search tasks across a workspace using Asana's typeahead/search API.
// Note: this endpoint requires a premium Asana plan.
searchTask(
  // 1) The search term (matches task name).
  $.data.searchTerm,
  // 2) Query params (assignee, completed, etc).
  {
    'assignee.any': $.data.assigneeGid,
    completed: false,
  }
);

Find User.code:
// Find a user in a workspace by email (or user gid).
request(
  `/workspaces/${$.configuration.workspaceGid}/users/${$.data.email}`,
  {
    query: { opt_fields: 'name,email' },
  }
);
